/**
 * ========================================
 * GOWA WEBHOOK CENTRAL HANDLER
 * ========================================
 * Sistem webhook terpusat untuk automation WhatsApp
 * Mendukung: Auto Reply, Command, Media Processing, VIP Access
 * Version: 1.0.0
 * ========================================
 */

// ============================================
// KONFIGURASI UTAMA
// ============================================
const CONFIG = {
  // Nomor bot (untuk deteksi self-message)
  BOT_NUMBER: "6282392115909",

  // Sub-workflow URLs (ganti dengan URL n8n Anda)
  WORKFLOWS: {
    AUTO_REPLY: "http://localhost:5678/webhook/auto-reply",
    COMMAND: "http://localhost:5678/webhook/command",
    AI_CHAT: "http://localhost:5678/webhook/ai-chat",
    MEDIA_HANDLER: "http://localhost:5678/webhook/media",
    GROUP_HANDLER: "http://localhost:5678/webhook/group",
    SEND_TO_SELF: "http://localhost:5678/webhook/send-to-self",
    VIP_HANDLER: "http://localhost:5678/webhook/vip"
  },

  // Blacklist (Official Accounts)
  BLACKLIST_KEYWORDS: [
    "rumahweb", "telkomsel", "indosat", "tri", "xl",
    "bank", "bca", "mandiri", "bri", "bni",
    "otp", "auth", "verify", "facebook", "whatsapp",
    "official", "team", "lazada", "shopee", "tokopedia"
  ],

  // Command prefix
  COMMAND_PREFIXES: ["!", "/", "."],

  // Timezone
  TIMEZONE: "Asia/Jakarta"
};

// ============================================
// UTILITY FUNCTIONS
// ============================================

function normalizePhone(phone) {
  if (!phone) return "";
  let cleaned = String(phone)
    .split(':')[0]
    .split('@')[0]
    .replace(/[^0-9]/g, '');
  if (cleaned.startsWith("08")) {
    cleaned = "62" + cleaned.substring(1);
  }
  if (!cleaned.startsWith("62")) {
    cleaned = "62" + cleaned;
  }
  return cleaned;
}

function parseCommand(text) {
  const regex = /^([.!/])\s*(\S+)(?:\s+(.*))?$/s;
  const match = text.trim().match(regex);
  if (!match) {
    return { isCommand: false, prefix: null, command: null, args: null };
  }
  return {
    isCommand: true,
    prefix: match[1],
    command: match[2].toLowerCase(),
    args: match[3] || null
  };
}

function isOfficialAccount(name) {
  if (!name) return false;
  const lowerName = name.toLowerCase();
  return CONFIG.BLACKLIST_KEYWORDS.some(keyword => 
    lowerName.includes(keyword)
  );
}

function getTimestamp() {
  return new Date().toLocaleString('id-ID', { 
    timeZone: CONFIG.TIMEZONE 
  });
}

// ============================================
// WEBHOOK PAYLOAD PARSER
// ============================================

function extractMessageContent(data) {
  let type = 'text';
  let text = '';
  let caption = '';
  let mediaUrl = '';

  if (data.message?.text || data.text || data.body) {
    type = 'text';
    text = data.message?.text || data.text || data.body || '';
  }
  else if (data.image || data.message?.imageMessage) {
    type = 'image';
    const img = data.image || data.message?.imageMessage;
    caption = img.caption || '';
    mediaUrl = img.media_path || img.url || '';
    text = caption;
  }
  else if (data.video || data.message?.videoMessage) {
    type = 'video';
    const vid = data.video || data.message?.videoMessage;
    caption = vid.caption || '';
    mediaUrl = vid.media_path || vid.url || '';
    text = caption;
  }
  else if (data.audio || data.message?.audioMessage) {
    type = 'audio';
    const aud = data.audio || data.message?.audioMessage;
    mediaUrl = aud.media_path || aud.url || '';
  }
  else if (data.ptt || data.message?.pttMessage) {
    type = 'ptt';
    const ptt = data.ptt || data.message?.pttMessage;
    mediaUrl = ptt.media_path || ptt.url || '';
  }
  else if (data.document || data.message?.documentMessage) {
    type = 'document';
    const doc = data.document || data.message?.documentMessage;
    caption = doc.caption || doc.fileName || '';
    mediaUrl = doc.media_path || doc.url || '';
    text = caption;
  }
  else if (data.location || data.message?.locationMessage) {
    type = 'location';
    const loc = data.location || data.message?.locationMessage;
    text = `Location: ${loc.latitude}, ${loc.longitude}`;
  }
  else if (data.contact || data.message?.contactMessage) {
    type = 'contact';
    const contact = data.contact || data.message?.contactMessage;
    text = `Contact: ${contact.displayName || contact.name || 'Unknown'}`;
  }

  const normalized = String(text || caption || '').trim().replace(/\s+/g, ' ');

  return {
    type: type,
    text: text,
    caption: caption,
    mediaUrl: mediaUrl,
    normalized: normalized
  };
}

function parseWebhookPayload(payload) {
  try {
    const body = payload.body || payload;
    const event = body.event || "message";
    const data = body.payload || body;

    const messageId = data.message?.id || data.id || "";
    const timestamp = data.timestamp || data.message?.timestamp || Date.now();

    const chatId = data.chat_id || data.from || data.key?.remoteJid || "";
    const participantJid = data.participant || data.sender_id || "";
    const pushName = data.pushname || data.notifyName || data.sender_name || "Unknown";

    const isGroup = chatId.endsWith('@g.us') || chatId.startsWith('120') || chatId.length > 18;
    const isStatus = chatId.includes('status@broadcast');

    const senderPhone = normalizePhone(isGroup ? participantJid : chatId);
    const targetChatId = normalizePhone(chatId);

    const isFromMe = (
      data.from_me === true ||
      data.key?.fromMe === true ||
      senderPhone === CONFIG.BOT_NUMBER
    );

    const isAck = event === 'message.ack';
    const messageContent = extractMessageContent(data);

    return {
      status: isFromMe || isAck || isStatus ? 'IGNORED' : 'VALID',
      event: event,
      timestamp: timestamp,
      chatId: targetChatId,
      senderPhone: senderPhone,
      isGroup: isGroup,
      isStatus: isStatus,
      pushName: pushName,
      isFromMe: isFromMe,
      isAck: isAck,
      isOfficialAccount: isOfficialAccount(pushName),
      messageId: messageId,
      messageType: messageContent.type,
      messageText: messageContent.text,
      normalizedText: messageContent.normalized,
      caption: messageContent.caption,
      mediaUrl: messageContent.mediaUrl,
      command: parseCommand(messageContent.text || messageContent.caption || ""),
      _raw: data,
      _timestamp: getTimestamp()
    };

  } catch (error) {
    return {
      status: 'ERROR',
      error: error.message,
      _raw: payload
    };
  }
}

// ============================================
// ROUTING LOGIC
// ============================================

function determineWorkflowRoute(parsedData) {
  if (parsedData.status !== 'VALID') {
    return { route: 'IGNORED', reason: parsedData.status };
  }

  if (parsedData.isOfficialAccount) {
    return { route: 'IGNORED', reason: 'OFFICIAL_ACCOUNT' };
  }

  if (parsedData.event.startsWith('group.')) {
    return { route: 'GROUP_HANDLER', priority: 'high' };
  }

  if (parsedData.command.isCommand) {
    const cmd = parsedData.command.command;
    if (cmd === 'sendme' || cmd === 'tome') {
      return { route: 'SEND_TO_SELF', priority: 'high' };
    }
    return { route: 'COMMAND', priority: 'high' };
  }

  if (parsedData.messageType !== 'text') {
    return { route: 'MEDIA_HANDLER', priority: 'medium' };
  }

  if (parsedData.normalizedText.length < 50) {
    return { route: 'AUTO_REPLY', priority: 'low' };
  }

  return { route: 'AI_CHAT', priority: 'medium' };
}

// ============================================
// MAIN PROCESSING
// ============================================

const items = $input.all();
const results = [];

for (const item of items) {
  const payload = item.json;
  const startTime = Date.now();

  const parsedData = parseWebhookPayload(payload);
  const routing = determineWorkflowRoute(parsedData);

  results.push({
    json: {
      // Parsed data untuk routing
      ...parsedData,

      // Routing decision
      route: routing.route,
      priority: routing.priority || 'none',
      reason: routing.reason || '',

      // Performance
      processingTime: Date.now() - startTime,
      processedAt: getTimestamp(),

      // Workflow URLs untuk HTTP Request nodes
      workflowUrl: CONFIG.WORKFLOWS[routing.route] || null
    }
  });
}

return results;
